func (r *Replica) handlePrepare(prepare *Prepare) {
	if prepare.Ballot > r.maxRecvBallot {
		r.maxRecvBallot = prepare.Ballot
	}

	inst := r.instanceSpace[prepare.Instance]
	if inst == nil {
		if prepare.Instance > r.crtInstance {
			r.crtInstance = prepare.Instance
		}
		r.instanceSpace[prepare.Instance] = &Instance{
			nil,
			r.defaultBallot[r.Id],
			r.defaultBallot[r.Id],
			PREPARING,
			nil}
		inst = r.instanceSpace[prepare.Instance]
	}

	if inst.status == COMMITTED {
		var pc Commit
		pc.LeaderId = prepare.LeaderId
		pc.Instance = prepare.Instance
		pc.Ballot = inst.vbal
		pc.Command = inst.cmds
		args := &pc
		r.SendMsg(pc.LeaderId, r.commitRPC, args)
		return
	}

	if inst.bal > prepare.Ballot {
	} else if inst.bal < prepare.Ballot {
		inst.bal = prepare.Ballot
		inst.status = PREPARED
		if r.crtInstance == prepare.Instance {
			r.defaultBallot[r.Id] = prepare.Ballot
		}
	}

	preply := &PrepareReply{prepare.Instance, inst.bal, inst.vbal, r.defaultBallot[r.Id], r.Id, inst.cmds}
	r.replyPrepare(prepare.LeaderId, preply)
}

func (r *Replica) handleAccept(accept *Accept) {
	inst := r.instanceSpace[accept.Instance]

	if accept.Ballot > r.maxRecvBallot {
		r.maxRecvBallot = accept.Ballot
	}

	if inst == nil {
		if accept.Instance > r.crtInstance {
			r.crtInstance = accept.Instance
		}
		r.instanceSpace[accept.Instance] = &Instance{
			accept.Command,
			accept.Ballot,
			accept.Ballot,
			ACCEPTED,
			nil}
		inst = r.instanceSpace[accept.Instance]
		r.recordInstanceMetadata(r.instanceSpace[accept.Instance])
		r.recordCommands(accept.Command)
		r.sync()
	} else if accept.Ballot < inst.bal {
		dlog.Printf("Smaller ballot %d < %d\n", accept.Ballot, inst.bal)
	} else if inst.status == COMMITTED {
		dlog.Printf("Already committed \n")
	} else {
		inst.cmds = accept.Command
		inst.bal = accept.Ballot
		inst.vbal = accept.Ballot
		inst.status = ACCEPTED
		r.recordInstanceMetadata(r.instanceSpace[accept.Instance])
		r.recordCommands(accept.Command)
		r.sync()
	}

	areply := &AcceptReply{accept.Instance, inst.bal}
	r.replyAccept(accept.LeaderId, areply)
}

func (r *Replica) handleCommit(commit *Commit) {
	inst := r.instanceSpace[commit.Instance]
	if inst == nil {
		if commit.Instance > r.crtInstance {
			r.crtInstance = commit.Instance
		}
		r.instanceSpace[commit.Instance] = &Instance{
			nil,
			r.defaultBallot[r.Id],
			r.defaultBallot[r.Id],
			PREPARING,
			nil}
		inst = r.instanceSpace[commit.Instance]
	}

	if inst != nil && inst.status == COMMITTED {
		return
	}

	if commit.Ballot < inst.bal {
		return
	}

	// FIXME timeout on client side?
	if inst.lb != nil && inst.lb.clientProposals != nil {
		for _, p := range inst.lb.clientProposals {
			r.ProposeChan <- p
		}
		inst.lb.clientProposals = nil
	}

	inst.cmds = commit.Command
	inst.bal = commit.Ballot
	inst.vbal = commit.Ballot
	inst.status = COMMITTED
	r.recordInstanceMetadata(r.instanceSpace[commit.Instance])
	r.recordCommands(commit.Command)
}

func (r *Replica) handleCommitShort(commit *CommitShort) {
	inst := r.instanceSpace[commit.Instance]
	if inst == nil {
		return
	}

	if inst.status == COMMITTED {
		return
	}

	if commit.Ballot < inst.bal {
		return
	}

	r.instanceSpace[commit.Instance].status = COMMITTED
	r.instanceSpace[commit.Instance].bal = commit.Ballot
	r.recordInstanceMetadata(r.instanceSpace[commit.Instance])
	r.recordCommands(r.instanceSpace[commit.Instance].cmds)
}

func (r *Replica) handlePrepareReply(preply *PrepareReply) {
	inst := r.instanceSpace[preply.Instance]
	lb := r.instanceSpace[preply.Instance].lb

	if preply.Ballot > r.maxRecvBallot {
		r.maxRecvBallot = preply.Ballot
	}

	if preply.Ballot < lb.lastTriedBallot {
		return
	}

	if preply.Ballot > lb.lastTriedBallot {
		lb.nacks++
		if lb.nacks+1 > r.N>>1 {
			if r.IsLeader {
				r.makeBallot(preply.Instance)
				r.bcastPrepare(preply.Instance)
			}
		}
		return
	}

	if preply.VBallot > lb.ballot {
		lb.ballot = preply.VBallot
		lb.cmds = preply.Command
	}

	lb.prepareOKs++
	if r.defaultBallot[preply.AcceptorId] < preply.DefaultBallot {
		r.defaultBallot[preply.AcceptorId] = preply.DefaultBallot
	}

	if lb.prepareOKs < r.Replica.ReadQuorumSize() && len(preply.Command) != 0 {
		r.totalRecNum += len(preply.Command)
		r.Println("totalRecNum:", r.totalRecNum)
	}

	// TODO: In the following we update lb.cmds,
	// ignoring `lb.cmds = preply.Command` executed
	// previously. This is strange

	if lb.prepareOKs+1 >= r.Replica.ReadQuorumSize() {
		if lb.clientProposals != nil {
			cmds := make([]state.Command, len(lb.clientProposals))
			for i := 0; i < len(lb.clientProposals); i++ {
				cmds[i] = lb.clientProposals[i].Command
			}
			lb.cmds = cmds
		} else {
			lb.cmds = state.NOOP()
		}
		inst.cmds = lb.cmds
		inst.bal = lb.lastTriedBallot
		inst.status = ACCEPTED

		m := int32(math.MaxInt32)
		count := 0
		for _, e := range r.defaultBallot {
			if e != -1 {
				count++
				if e < m {
					m = e
				}
			}
		}
		if count >= r.Replica.ReadQuorumSize()-1 && m > r.smallestDefaultBallot {
			r.smallestDefaultBallot = m
		}

		r.recordInstanceMetadata(r.instanceSpace[preply.Instance])
		r.sync()
		r.bcastAccept(preply.Instance)
		if len(inst.cmds) != 0 {
			r.totalSendNum += len(inst.cmds)
			r.Println("totalSendNum:", r.totalSendNum)
		}
	}
}

func (r *Replica) handleAcceptReply(areply *AcceptReply) {
	inst := r.instanceSpace[areply.Instance]
	lb := r.instanceSpace[areply.Instance].lb

	if areply.Ballot > r.maxRecvBallot {
		r.maxRecvBallot = areply.Ballot
	}

	if inst.status >= COMMITTED {
		return
	}

	if areply.Ballot < lb.lastTriedBallot {
		return
	}

	if areply.Ballot > lb.lastTriedBallot {
		lb.nacks++
		if lb.nacks+1 >= r.Replica.WriteQuorumSize() {
			if r.IsLeader {
				r.makeBallot(areply.Ballot)
				r.bcastPrepare(areply.Instance)
			}
		}
		return
	}

	lb.acceptOKs++
	if lb.acceptOKs+1 >= r.Replica.WriteQuorumSize() {
		inst = r.instanceSpace[areply.Instance]
		inst.status = COMMITTED
		r.recordInstanceMetadata(r.instanceSpace[areply.Instance])
		r.sync()

		r.bcastCommit(areply.Instance, inst.bal, inst.cmds)
		if lb.clientProposals != nil && !r.Dreply {
			for i := 0; i < len(inst.cmds); i++ {
				propreply := &defs.ProposeReplyTS{
					TRUE,
					lb.clientProposals[i].CommandId,
					state.NIL(),
					lb.clientProposals[i].Timestamp}
				r.ReplyProposeTS(propreply, lb.clientProposals[i].Reply, lb.clientProposals[i].Mutex)
			}
		}
	}
}

func (r *Replica) recover(instance int32) {
	if r.instanceSpace[instance] == nil {
		r.instanceSpace[instance] = &Instance{
			nil,
			r.defaultBallot[r.Id],
			r.defaultBallot[r.Id],
			PREPARING,
			nil}

	}

	if r.instanceSpace[instance].lb == nil {
		r.instanceSpace[instance].lb = &LeaderBookkeeping{nil, 0, 0, 0, -1, nil, -1}
	}

	r.makeBallot(instance)
	r.bcastPrepare(instance)
}

func (r *Replica) executeCommands() {
	timeout := int64(0)
	problemInstance := int32(0)

	for !r.Shutdown {
		executed := false

		// FIXME idempotence
		for i := r.executedUpTo + 1; i <= r.crtInstance; i++ {
			inst := r.instanceSpace[i]
			if inst != nil && inst.cmds != nil && inst.status == COMMITTED {
				for j := 0; j < len(inst.cmds); j++ {
					if r.Dreply && inst.lb != nil && inst.lb.clientProposals != nil {
						val := inst.cmds[j].Execute(r.State)
						propreply := &defs.ProposeReplyTS{
							TRUE,
							inst.lb.clientProposals[j].CommandId,
							val,
							inst.lb.clientProposals[j].Timestamp}
						r.ReplyProposeTS(propreply, inst.lb.clientProposals[j].Reply, inst.lb.clientProposals[j].Mutex)
					} else if inst.cmds[j].Op == state.PUT {
						inst.cmds[j].Execute(r.State)
					}
				}
				executed = true
				r.executedUpTo++
			} else {
				if i == problemInstance {
					timeout += SLEEP_TIME_NS
					if timeout >= COMMIT_GRACE_PERIOD {
						for k := problemInstance; k <= r.crtInstance; k++ {
							r.instancesToRecover <- k
						}
						problemInstance = 0
						timeout = 0
					}
				} else {
					problemInstance = i
					timeout = 0
				}
				break
			}
		}

		if !executed {
			r.M.Lock()
			r.M.Unlock() // FIXME for cache coherence
			time.Sleep(SLEEP_TIME_NS)
		}
	}
}

package master

import (
	"errors"
	"fmt"
	"math"
	"net"
	"net/http"
	"net/rpc"
	"os/exec"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/imdea-software/swiftpaxos/config"
	"github.com/imdea-software/swiftpaxos/dlog"
	"github.com/imdea-software/swiftpaxos/replica/defs"
)

type Master struct {
	*dlog.Logger

	N          int
	port       int
	nodeList   []string
	addrList   []string
	portList   []int
	lock       *sync.Mutex
	nodes      []*rpc.Client
	leader     []bool
	alive      []bool
	latencies  []float64
	finishInit bool
	initCond   *sync.Cond
	nextLeader int
	config     *config.Config
}

func New(N, port int, config *config.Config, logger *dlog.Logger) *Master {
	master := &Master{
		Logger: logger,

		N:          N,
		port:       port,
		nodeList:   make([]string, 0, N),
		addrList:   make([]string, 0, N),
		portList:   make([]int, 0, N),
		lock:       new(sync.Mutex),
		nodes:      make([]*rpc.Client, N),
		leader:     make([]bool, N),
		alive:      make([]bool, N),
		latencies:  make([]float64, N),
		finishInit: false,
		nextLeader: -1,
		config:     config,
	}
	master.initCond = sync.NewCond(master.lock)
	return master
}

func (master *Master) Run() {
	master.Printf("master starting on port %d", master.port)
	master.Printf("waiting for %d replicas", master.N)

	rpc.Register(master)
	rpc.HandleHTTP()
	l, err := net.Listen("tcp", fmt.Sprintf(":%d", master.port))
	if err != nil {
		master.Fatal("master listen error:", err)
	}
	go master.run()
	http.Serve(l, nil)
}

func (master *Master) run() {
	for {
		master.lock.Lock()
		if len(master.nodeList) == master.N {
			master.lock.Unlock()
			break
		}
		master.lock.Unlock()
		time.Sleep(time.Second)
	}
	time.Sleep(2 * time.Second)

	for i := 0; i < master.N; {
		var err error
		addr := fmt.Sprintf("%s:%d", master.addrList[i], master.portList[i]+1000)
		master.nodes[i], err = rpc.DialHTTP("tcp", addr)
		if err != nil {
			master.Printf("error connecting to replica %d (%v), retrying...", i, addr)
			time.Sleep(time.Second)
		} else {
			btlReply := defs.NewBeTheLeaderReply()
			if master.leader[i] {
				err = master.nodes[i].Call("Replica.BeTheLeader", &defs.BeTheLeaderArgs{}, btlReply)
				if err != nil {
					master.Fatal("Not today Zurg!")
				}
				defs.UpdateBeTheLeaderReply(btlReply)
				leaderI := i
				if btlReply.Leader != -1 {
					leaderI = int(btlReply.Leader)
					master.leader[i] = false
					master.leader[leaderI] = true
				}
				master.nextLeader = int(btlReply.NextLeader)
				if leaderI == i {
					master.Printf("replica %d is the new leader", leaderI)
				} else if leaderI < i {
					i = leaderI - 1
				}
			}
			i++
		}
	}

	var new_leader bool
	pingNode := func(i int, node *rpc.Client) {
		err := node.Call("Replica.Ping", &defs.PingArgs{}, &defs.PingReply{})
		if err != nil {
			master.alive[i] = false
			if master.leader[i] {
				new_leader = true
				master.leader[i] = false
			}
		} else {
			master.alive[i] = true
		}
	}
	master.lock.Lock()
	for i, node := range master.nodes {
		pingNode(i, node)
	}
	// initialization is finished
	// (i.e., `alive` has been computed)
	master.finishInit = true
	master.initCond.Broadcast()
	master.lock.Unlock()

	beTheLeader := func(i int) error {
		if master.alive[i] {
			btlReply := defs.NewBeTheLeaderReply()
			err := master.nodes[i].Call("Replica.BeTheLeader", &defs.BeTheLeaderArgs{}, btlReply)
			if err == nil {
				defs.UpdateBeTheLeaderReply(btlReply)
				leaderI := i
				if btlReply.Leader != -1 {
					// TODO: need to set leader[old_leader] to false?
					leaderI = int(btlReply.Leader)
				}
				master.leader[leaderI] = true
				master.nextLeader = int(btlReply.NextLeader)
				master.Printf("replica %d is the new leader", leaderI)
				return nil
			}
			return err
		}
		return errors.New("dead")
	}

	for {
		time.Sleep(3 * time.Second)
		new_leader = false
		for i, node := range master.nodes {
			pingNode(i, node)
		}

		if !new_leader {
			continue
		}
		if master.nextLeader != -1 {
			if beTheLeader(master.nextLeader) == nil {
				continue
			}
		}
		for i := range master.nodes {
			if beTheLeader(i) == nil {
				break
			}
		}
	}
}

func (master *Master) Register(args *defs.RegisterArgs, reply *defs.RegisterReply) error {
	master.lock.Lock()
	defer master.lock.Unlock()

	nlen := len(master.nodeList)
	index := nlen

	addrPort := fmt.Sprintf("%s:%d", args.Addr, args.Port)

	for i, ap := range master.nodeList {
		if addrPort == ap {
			index = i
			break
		}
	}

	if index == nlen {
		master.nodeList = master.nodeList[0 : nlen+1]
		master.nodeList[nlen] = addrPort
		master.addrList = master.addrList[0 : nlen+1]
		master.addrList[nlen] = args.Addr
		master.portList = master.portList[0 : nlen+1]
		master.portList[nlen] = args.Port
		master.leader[index] = false
		nlen++

		addr := args.Addr
		if addr == "" {
			addr = "127.0.0.1"
		}
		out, err := exec.Command("ping", addr, "-c 2", "-q").Output()
		if err == nil {
			master.latencies[index], _ =
				strconv.ParseFloat(strings.Split(string(out), "/")[4], 64)
			master.Printf("node %v [%v] -> %v", index,
				master.nodeList[index], master.latencies[index])
		} else {
			master.Fatal("cannot connect to " + addr)
		}
	}

	if nlen == master.N {
		reply.Ready = true
		reply.ReplicaId = index
		reply.NodeList = master.nodeList
		reply.IsLeader = false

		minLatency := math.MaxFloat64
		leader := -1

		if master.config.Leader != nil {
			if addrPort == *master.config.Leader {
				leader = index
			}
		} else {
			for i := 0; i < len(master.leader); i++ {
				if master.latencies[i] < minLatency {
					minLatency = master.latencies[i]
					leader = i
				}
			}
		}

		if leader == index {
			master.leader[index] = true
			reply.IsLeader = true
		}

	} else {
		reply.Ready = false
	}

	return nil
}

func (master *Master) GetLeader(args *defs.GetLeaderArgs, reply *defs.GetLeaderReply) error {
	master.lock.Lock()
	defer master.lock.Unlock()

	for i, l := range master.leader {
		if l {
			*reply = defs.GetLeaderReply{
				LeaderId: i,
			}
			break
		}
	}
	return nil
}

func (master *Master) GetReplicaList(args *defs.GetReplicaListArgs, reply *defs.GetReplicaListReply) error {
	master.lock.Lock()

	for !master.finishInit {
		master.initCond.Wait()
	}

	if len(master.nodeList) == master.N {
		reply.Ready = true
	} else {
		reply.Ready = false
	}

	reply.ReplicaList = make([]string, 0)
	reply.AliveList = make([]bool, 0)
	for i, node := range master.nodeList {
		reply.ReplicaList = append(reply.ReplicaList, node)
		reply.AliveList = append(reply.AliveList, master.alive[i])
	}

	master.Printf("nodes list %v", reply.ReplicaList)
	master.lock.Unlock()
	return nil
}

