func (t *CommitShort) New() fastrpc.Serializable {
	return new(CommitShort)
}
func (t *CommitShort) BinarySize() (nbytes int, sizeKnown bool) {
	return 16, true
}

type CommitShortCache struct {
	mu    sync.Mutex
	cache []*CommitShort
}

func NewCommitShortCache() *CommitShortCache {
	c := &CommitShortCache{}
	c.cache = make([]*CommitShort, 0)
	return c
}

func (p *CommitShortCache) Get() *CommitShort {
	var t *CommitShort
	p.mu.Lock()
	if len(p.cache) > 0 {
		t = p.cache[len(p.cache)-1]
		p.cache = p.cache[0:(len(p.cache) - 1)]
	}
	p.mu.Unlock()
	if t == nil {
		t = &CommitShort{}
	}
	return t
}
func (p *CommitShortCache) Put(t *CommitShort) {
	p.mu.Lock()
	p.cache = append(p.cache, t)
	p.mu.Unlock()
}
func (t *CommitShort) Marshal(wire io.Writer) {
	var b [16]byte
	var bs []byte
	bs = b[:16]
	tmp32 := t.LeaderId
	bs[0] = byte(tmp32)
	bs[1] = byte(tmp32 >> 8)
	bs[2] = byte(tmp32 >> 16)
	bs[3] = byte(tmp32 >> 24)
	tmp32 = t.Instance
	bs[4] = byte(tmp32)
	bs[5] = byte(tmp32 >> 8)
	bs[6] = byte(tmp32 >> 16)
	bs[7] = byte(tmp32 >> 24)
	tmp32 = t.Count
	bs[8] = byte(tmp32)
	bs[9] = byte(tmp32 >> 8)
	bs[10] = byte(tmp32 >> 16)
	bs[11] = byte(tmp32 >> 24)
	tmp32 = t.Ballot
	bs[12] = byte(tmp32)
	bs[13] = byte(tmp32 >> 8)
	bs[14] = byte(tmp32 >> 16)
	bs[15] = byte(tmp32 >> 24)
	wire.Write(bs)
}

func (t *CommitShort) Unmarshal(wire io.Reader) error {
	var b [16]byte
	var bs []byte
	bs = b[:16]
	if _, err := io.ReadAtLeast(wire, bs, 16); err != nil {
		return err
	}
	t.LeaderId = int32((uint32(bs[0]) | (uint32(bs[1]) << 8) | (uint32(bs[2]) << 16) | (uint32(bs[3]) << 24)))
	t.Instance = int32((uint32(bs[4]) | (uint32(bs[5]) << 8) | (uint32(bs[6]) << 16) | (uint32(bs[7]) << 24)))
	t.Count = int32((uint32(bs[8]) | (uint32(bs[9]) << 8) | (uint32(bs[10]) << 16) | (uint32(bs[11]) << 24)))
	t.Ballot = int32((uint32(bs[12]) | (uint32(bs[13]) << 8) | (uint32(bs[14]) << 16) | (uint32(bs[15]) << 24)))
	return nil
}

package replica

import (
	"github.com/imdea-software/swiftpaxos/replica/defs"
	fastrpc "github.com/imdea-software/swiftpaxos/rpc"
)

const (
	SEND_ALL = iota
	SEND_QUORUM
	SEND_EXCEPT
	SEND_SINGLE
	SEND_CLIENT
	SEND_ALL_EXCEPT
)

type SendType int32

const ARGS_NUM = defs.CHAN_BUFFER_SIZE

type SendArg struct {
	msg      fastrpc.Serializable
	rpc      uint8
	quorum   Quorum
	sendType SendType
	id       int32
	free     func()
}

type Sender chan SendArg

func NewSender(r *Replica) Sender {
	s := Sender(make(chan SendArg, ARGS_NUM))

	go func() {
		for !r.Shutdown {
			arg := <-s
			switch arg.sendType {
			case SEND_ALL:
				sendToAll(r, arg.msg, arg.rpc)
			case SEND_QUORUM:
				sendToQuorum(r, arg.quorum, arg.msg, arg.rpc)
			case SEND_EXCEPT:
				sendExcept(r, arg.quorum, arg.msg, arg.rpc)
			case SEND_CLIENT:
				r.SendClientMsg(arg.id, arg.rpc, arg.msg)
			case SEND_SINGLE:
				r.SendMsg(arg.id, arg.rpc, arg.msg)
			case SEND_ALL_EXCEPT:
				sendToAllExcept(r, arg.id, arg.msg, arg.rpc)
			}
			if arg.free != nil {
				arg.free()
			}
		}
	}()

	return s
}

func (s Sender) SendToAllAndFree(msg fastrpc.Serializable,
	rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		sendType: SEND_ALL,
		free:     free,
	}
}

func (s Sender) SendToAllExecptAndFree(except int32, msg fastrpc.Serializable, rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		sendType: SEND_ALL_EXCEPT,
		free:     free,
		id:       except,
	}
}

func (s Sender) SendToQuorumAndFree(q Quorum,
	msg fastrpc.Serializable, rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		quorum:   q,
		sendType: SEND_QUORUM,
		free:     free,
	}
}

func (s Sender) SendExceptAndFree(q Quorum,
	msg fastrpc.Serializable, rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		quorum:   q,
		sendType: SEND_EXCEPT,
		free:     free,
	}
}

func (s Sender) SendToClientAndFree(cid int32,
	msg fastrpc.Serializable, rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		id:       cid,
		sendType: SEND_CLIENT,
		free:     free,
	}
}

func (s Sender) SendToAndFree(id int32,
	msg fastrpc.Serializable, rpc uint8, free func()) {
	s <- SendArg{
		msg:      msg,
		rpc:      rpc,
		id:       id,
		sendType: SEND_SINGLE,
		free:     free,
	}
}

func (s Sender) SendToAll(msg fastrpc.Serializable, rpc uint8) {
	s.SendToAllAndFree(msg, rpc, nil)
}

func (s Sender) SendToAllExecpt(except int32, msg fastrpc.Serializable, rpc uint8) {
	s.SendToAllExecptAndFree(except, msg, rpc, nil)
}

func (s Sender) SendToQuorum(q Quorum, msg fastrpc.Serializable, rpc uint8) {
	s.SendToQuorumAndFree(q, msg, rpc, nil)
}

func (s Sender) SendExcept(q Quorum, msg fastrpc.Serializable, rpc uint8) {
	s.SendExceptAndFree(q, msg, rpc, nil)
}

func (s Sender) SendToClient(cid int32, msg fastrpc.Serializable, rpc uint8) {
	s.SendToClientAndFree(cid, msg, rpc, nil)
}

func (s Sender) SendTo(id int32, msg fastrpc.Serializable, rpc uint8) {
	s.SendToAndFree(id, msg, rpc, nil)
}

func sendToAll(r *Replica, msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendToAllExcept(r *Replica, except int32, msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if p == except {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendToQuorum(r *Replica, q Quorum,
	msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if !q.Contains(p) {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendExcept(r *Replica, q Quorum,
	msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if q.Contains(p) {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

