func (r *Replica) recover(instance int32) {
	if r.instanceSpace[instance] == nil {
		r.instanceSpace[instance] = &Instance{
			nil,
			r.defaultBallot[r.Id],
			r.defaultBallot[r.Id],
			PREPARING,
			nil}

	}

	if r.instanceSpace[instance].lb == nil {
